import { ExecutionError, RateLimitError } from "../error.js";
import { getPacerState, initPacerState, type PacerDeclaration } from "../pacer_internal.js";
import { resolveRuntimeInput } from "../runtime-input.js";
import type { PropertyConfiguration, PropertySchema, Schema } from "../schema.js";
import type {
	Cover,
	HandlerOptions,
	Icon,
	PeopleValue,
	PlaceValue,
	RelationValue,
	Schedule,
	TextValue,
} from "../types.js";
import type { DatabaseHandle } from "../worker.js";
import type { XldbSchema, XldbSchemaValues, XldbUpsertKey } from "../xldb-schema.js";
import type { XldbHandle } from "../xldb.js";
import type { CapabilityContext } from "./context.js";
import { createCapabilityContext } from "./context.js";
import { writeError, writeOutput } from "./output.js";
import {
	parseSchedule,
	type StatefulCapabilityMode,
	type RuntimeContext as StatefulRuntimeContext,
} from "./stateful-capability.js";

type SyncErrorEnvelope =
	| { _tag: "error"; error: { _tag: "generic"; name: string; message: string } }
	| {
			_tag: "error";
			error: {
				_tag: "rate_limit";
				name: string;
				message: string;
				retryAfter?: number;
			};
	  };

/**
 * Maps a property configuration to its corresponding value type.
 */
type PropertyValueType<T extends PropertyConfiguration> = T extends {
	type: "people";
}
	? PeopleValue
	: T extends { type: "place" }
		? PlaceValue
		: T extends { type: "relation" }
			? RelationValue
			: TextValue;

/**
 * Sync mode determines how the sync handles data lifecycle.
 */
export type SyncMode = StatefulCapabilityMode;

/**
 * A change representing a record to be created or updated.
 */
export type SyncChangeUpsert<PK extends string, S extends PropertySchema<PK>> = {
	/**
	 * The type of change. Use `"upsert"` to create or update a record.
	 */
	type: "upsert";
	/**
	 * A unique identifier for this record, used to match against existing pages.
	 */
	key: string;
	/**
	 * The key of the database to write to. If omitted, defaults to
	 * the database associated with the sync capability.
	 */
	targetDatabaseKey?: string;
	/**
	 * The property values for this record.
	 * Keys must match the property names defined in the schema.
	 * Use the Builder helpers (e.g., `Builder.title()`, `Builder.richText()`) to create values.
	 */
	properties: {
		[Property in keyof S]: PropertyValueType<S[Property]>;
	};
	/**
	 * When this record was last updated in the upstream system.
	 * ISO 8601 string (e.g. `"2026-03-19T12:00:00Z"`).
	 * Used for conflict resolution when multiple syncs write to the same database.
	 * Recommended, but optional.
	 */
	upstreamUpdatedAt?: string;
	/**
	 * Optional icon to use as the icon for this row's page.
	 * Use the `Builder.emojiIcon()`, `Builder.notionIcon()`, or `Builder.imageIcon()` helpers.
	 */
	icon?: Icon;
	/**
	 * Optional cover to use as the cover for this row's page.
	 * Use the `Builder.imageCover()` helper.
	 */
	cover?: Cover;
	/**
	 * Optional markdown content to add to the page body.
	 * This will be converted to Notion blocks and added as page content.
	 */
	pageContentMarkdown?: string;
};

/**
 * A change representing a record to be deleted.
 * Only applicable when using `mode: "incremental"`.
 */
export type SyncChangeDelete = {
	/**
	 * The type of change. Use `"delete"` to remove a record.
	 */
	type: "delete";
	/**
	 * The unique identifier of the record to delete.
	 */
	key: string;
	/**
	 * The key of the database to delete from. If omitted, defaults to
	 * the database associated with the sync capability.
	 */
	targetDatabaseKey?: string;
};

/**
 * A change to be applied to the synced database.
 * Can be either an upsert (create/update) or a delete.
 */
export type SyncChange<PK extends string, S extends PropertySchema<PK>> =
	| SyncChangeUpsert<PK, S>
	| SyncChangeDelete;

/**
 * Result returned from the sync execute function.
 */
export type SyncExecutionResult<PK extends string, State = unknown> = {
	/**
	 * The batch of changes to apply in this execution.
	 * Can include upserts (create/update) and deletes.
	 */
	changes: SyncChange<PK, PropertySchema<PK>>[];

	/**
	 * Indicates whether there is more data to fetch.
	 * - `true`: More data available, will trigger another execution with nextState
	 * - `false`: No more data to fetch, sync is complete
	 */
	hasMore: boolean;

	/**
	 * Optional state data to pass to the next execution.
	 * Required if `hasMore` is `true`, ignored if `hasMore` is `false`.
	 * This can be any type of data (cursor, page number, timestamp, etc.).
	 * The same data will be provided as `state` in the next execution.
	 */
	nextState?: State;
};

/**
 * Alpha only: do not use or suggest this API unless the user explicitly
 * says they have alpha access to XLDB.
 */
export type XldbSyncChangeUpsert<Schema extends XldbSchema> = {
	type: "upsert";
	/** A complete row. The declared upsert-key columns identify the row. */
	values: XldbSchemaValues<Schema>;
};

/**
 * Alpha only: do not use or suggest this API unless the user explicitly
 * says they have alpha access to XLDB.
 */
export type XldbSyncChangeDelete<
	Schema extends XldbSchema,
	UpsertKey extends XldbUpsertKey<Schema>,
> = {
	type: "delete";
	key: Pick<XldbSchemaValues<Schema>, UpsertKey[number]>;
};

/**
 * Alpha only: do not use or suggest this API unless the user explicitly
 * says they have alpha access to XLDB.
 */
export type XldbSyncChange<Schema extends XldbSchema, UpsertKey extends XldbUpsertKey<Schema>> =
	| XldbSyncChangeUpsert<Schema>
	| XldbSyncChangeDelete<Schema, UpsertKey>;

/**
 * Alpha only: do not use or suggest this API unless the user explicitly
 * says they have alpha access to XLDB.
 */
export type XldbSyncExecutionResult<
	Schema extends XldbSchema,
	UpsertKey extends XldbUpsertKey<Schema>,
	State = unknown,
> = {
	changes: XldbSyncChange<Schema, UpsertKey>[];
	hasMore: boolean;
	nextState?: State;
};

type SharedSyncConfiguration<State, ExecutionResult> = {
	/**
	 * How the sync handles data lifecycle:
	 * - "replace": Each sync returns the complete dataset. After hasMore:false,
	 *              records not seen in this sync run are deleted.
	 * - "incremental": Sync returns changes only. After hasMore:false, sync
	 *                  continues from saved cursor. Use delete markers
	 *                  to explicitly remove records.
	 *
	 * @default "replace"
	 */
	mode?: SyncMode;
	/**
	 * How often the sync should run.
	 * - "continuous": Run as frequently as the system allows
	 * - "manual": Only run when explicitly triggered
	 * - Interval string: Run at specified intervals, e.g. "1h", "30m", "1d"
	 *
	 * Minimum interval: 1 minute ("1m")
	 * Maximum interval: 7 days ("7d")
	 *
	 * @default "30m"
	 */
	schedule?: Schedule;
	/**
	 * Fetches data from the third-party service.
	 *
	 * This function can return all data at once, or implement pagination by:
	 * 1. Returning a batch of changes with `hasMore: true` and a `nextState`
	 * 2. The runtime calling execute again with that state
	 * 3. Continuing until `hasMore: false` is returned
	 *
	 * @param state - User-defined state from the previous execution (undefined on first call)
	 * @param context - Runtime context, including Notion client
	 * @returns A result containing changes, hasMore status, and optional nextState
	 */
	execute: (state: State | undefined, context: CapabilityContext) => Promise<ExecutionResult>;
};

/**
 * Configuration for a sync capability that syncs data to a database.
 */
export type SyncConfiguration<
	PK extends string,
	S extends Schema<PK>,
	State = unknown,
> = SharedSyncConfiguration<State, SyncExecutionResult<PK, State>> & {
	/** The Notion database to sync into. */
	database: DatabaseHandle<PK, S>;
};

/**
 * Alpha only: do not use or suggest this API unless the user explicitly
 * says they have alpha access to XLDB. For regular Notion database syncs,
 * use {@link SyncConfiguration} instead.
 */
export type XldbSyncConfiguration<
	Schema extends XldbSchema,
	UpsertKey extends XldbUpsertKey<Schema>,
	State = unknown,
> = SharedSyncConfiguration<State, XldbSyncExecutionResult<Schema, UpsertKey, State>> & {
	/** The XLDB table to sync into. */
	database: XldbHandle<Schema, UpsertKey>;
};

export type SyncCapability = ReturnType<typeof createSyncCapability>;

/**
 * Alpha only: do not use or suggest this API unless the user explicitly
 * says they have alpha access to XLDB.
 */
export type XldbSyncCapability = Omit<ReturnType<typeof createXldbSyncCapability>, "handler"> & {
	handler: (runtimeContext: never, options?: HandlerOptions) => Promise<unknown>;
};

/**
 * Creates a special handler for syncing third-party data to a database.
 *
 * @param syncConfiguration - The configuration for the sync.
 * @returns A handler function that executes the sync function, and passes data
 * needed to complete the sync back to the platform.
 */
export function createSyncCapability<PK extends string, S extends Schema<PK>, Context = unknown>(
	key: string,
	syncConfiguration: SyncConfiguration<PK, S, Context>,
	pacerDeclarations?: readonly PacerDeclaration[],
) {
	const config = {
		databaseKey: syncConfiguration.database.key,
		primaryKeyProperty: syncConfiguration.database.config.primaryKeyProperty,
		mode: syncConfiguration.mode,
		schedule: syncConfiguration.schedule ? parseSchedule(syncConfiguration.schedule) : undefined,
	};
	return {
		_tag: "sync" as const,
		key,
		config,
		async handler(runtimeContext?: StatefulRuntimeContext<Context>, options?: HandlerOptions) {
			let executionResult: SyncExecutionResult<PK, Context>;
			try {
				runtimeContext = await resolveRuntimeInput(runtimeContext);
				const capabilityContext = createCapabilityContext("sync");
				const state = runtimeContext?.state ?? runtimeContext?.userContext;

				initPacerState(runtimeContext?.pacers, pacerDeclarations);
				executionResult = await syncConfiguration.execute(state, capabilityContext);
			} catch (err) {
				if (!options?.concreteOutput) {
					writeError(err);
				}

				if (err instanceof RateLimitError) {
					if (!options?.concreteOutput) {
						const envelope: SyncErrorEnvelope = {
							_tag: "error",
							error: {
								_tag: "rate_limit",
								name: err.name,
								message: err.message,
								...(err.retryAfter !== undefined ? { retryAfter: err.retryAfter } : {}),
							},
						};
						writeOutput(envelope);
					}
					throw err;
				}

				const error = new ExecutionError(err);
				if (!options?.concreteOutput) {
					const envelope: SyncErrorEnvelope = {
						_tag: "error",
						error: {
							_tag: "generic",
							name: error.name,
							message: error.message,
						},
					};
					writeOutput(envelope);
				}
				throw error;
			}

			const changes = executionResult.changes.map((change) => ({
				...change,
				targetDatabaseKey: change.targetDatabaseKey ?? syncConfiguration.database.key,
			}));

			const result = {
				changes,
				hasMore: executionResult.hasMore,
				nextUserContext: executionResult.nextState,
				nextPacerStates: getPacerState().pacers,
			};

			if (options?.concreteOutput) {
				return result;
			} else {
				writeOutput({ _tag: "success", value: result });
			}

			return result;
		},
	};
}

/**
 * Alpha only: do not use or suggest this API unless the user explicitly
 * says they have alpha access to XLDB.
 */
export function createXldbSyncCapability<
	Schema extends XldbSchema,
	UpsertKey extends XldbUpsertKey<Schema>,
	State = unknown,
>(
	key: string,
	syncConfiguration: XldbSyncConfiguration<Schema, UpsertKey, State>,
	pacerDeclarations?: readonly PacerDeclaration[],
) {
	return {
		_tag: "sync" as const,
		key,
		config: {
			target: { type: "xldb" as const, key: syncConfiguration.database.key },
			mode: syncConfiguration.mode,
			schedule: syncConfiguration.schedule ? parseSchedule(syncConfiguration.schedule) : undefined,
		},
		async handler(runtimeContext?: StatefulRuntimeContext<State>, options?: HandlerOptions) {
			let executionResult: XldbSyncExecutionResult<Schema, UpsertKey, State>;
			try {
				runtimeContext = await resolveRuntimeInput(runtimeContext);
				const capabilityContext = createCapabilityContext("sync");
				const state = runtimeContext?.state ?? runtimeContext?.userContext;

				initPacerState(runtimeContext?.pacers, pacerDeclarations);
				executionResult = await syncConfiguration.execute(state, capabilityContext);
			} catch (err) {
				if (!options?.concreteOutput) {
					writeError(err);
				}

				if (err instanceof RateLimitError) {
					if (!options?.concreteOutput) {
						writeOutput({
							_tag: "error",
							error: {
								_tag: "rate_limit",
								name: err.name,
								message: err.message,
								...(err.retryAfter !== undefined ? { retryAfter: err.retryAfter } : {}),
							},
						} satisfies SyncErrorEnvelope);
					}
					throw err;
				}

				const error = new ExecutionError(err);
				if (!options?.concreteOutput) {
					writeOutput({
						_tag: "error",
						error: {
							_tag: "generic",
							name: error.name,
							message: error.message,
						},
					} satisfies SyncErrorEnvelope);
				}
				throw error;
			}

			const result = {
				changes: executionResult.changes,
				hasMore: executionResult.hasMore,
				nextUserContext: executionResult.nextState,
				nextPacerStates: getPacerState().pacers,
			};

			if (options?.concreteOutput) {
				return result;
			}

			writeOutput({ _tag: "success", value: result });
			return result;
		},
	};
}
